import React, { useState } from 'react';
import axios from 'axios';

export default function TeacherContent({ userName, teachingSubject, materials, fetchData }) {
  const [formTitle, setFormTitle] = useState('');
  const [formGrade, setFormGrade] = useState('Grade 10');
  const [formType, setFormType] = useState('PDF');
  const [formFilePath, setFormFilePath] = useState('');

  const handlePublishLesson = (e) => {
    e.preventDefault();
    const payload = { title: formTitle, material_type: formType, file_path: formFilePath, grade: formGrade, subject: teachingSubject, teacher_name: userName };

    axios.post('http://localhost:8081/api/add-material', payload).then(res => {
      if (res.data.status === "Success") {
        alert("✅ Lesson Material Published!");
        fetchData(); setFormTitle(''); setFormFilePath('');
      }
    });
  };

  const handleDeleteMaterial = (id) => {
    if (window.confirm("Delete this material?")) {
      axios.delete(`http://localhost:8081/api/delete-material/${id}`).then(() => fetchData());
    }
  };

  return (
    <div style={{ animation: 'fadeIn 0.5s' }}>
      <h2 style={{ color: '#1e293b', marginBottom: '20px' }}>📤 Upload Lesson Materials</h2>
      <div style={{ backgroundColor: 'white', padding: '35px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', marginBottom: '30px' }}>
        <form onSubmit={handlePublishLesson} style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
          <input type="text" placeholder="Lesson Title" value={formTitle} onChange={e => setFormTitle(e.target.value)} required style={styles.input} />
          <div style={{ display: 'flex', gap: '20px' }}>
            <select value={formGrade} onChange={e => setFormGrade(e.target.value)} style={{...styles.input, flex: 1}}><option>Grade 9</option><option>Grade 10</option><option>Grade 11</option></select>
            <select value={formType} onChange={e => setFormType(e.target.value)} style={{...styles.input, flex: 1}}><option value="PDF">PDF Handout</option><option value="Video">Video Lesson</option></select>
          </div>
          <input type="text" placeholder="File Path / YouTube URL" value={formFilePath} onChange={e => setFormFilePath(e.target.value)} required style={styles.input} />
          <button type="submit" style={styles.btn}>+ Publish Lesson</button>
        </form>
      </div>

      <div style={{ backgroundColor: 'white', padding: '20px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ borderBottom: '2px solid #e2e8f0', color: '#64748b', fontSize: '13px' }}>
              <th>Title</th><th>Type</th><th>Grade</th><th>Action</th>
            </tr>
          </thead>
          <tbody>
            {materials.map(m => (
              <tr key={m.id} style={{ borderBottom: '1px solid #f1f5f9', fontSize: '14px' }}>
                <td style={{ padding: '12px 10px', fontWeight: 'bold' }}>{m.title}</td>
                <td>{m.material_type}</td><td>{m.grade}</td>
                <td><button onClick={() => handleDeleteMaterial(m.id)} style={{ background: 'none', border: 'none', cursor: 'pointer' }}>🗑️</button></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

const styles = {
  input: { width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc' },
  btn: { padding: '14px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }
};
